// Komikan rules and agent inference. This mirrors src/komikan/game.py and policy.py;
// tests/test_web_engine.py checks that both engines agree. Board data is generated by Python.
(function (root) {
  "use strict";

  const KOMIKELU = 0, TREWAS = 1, DRAW = 2;

  function createEngine(data) {
    const { coords, actions, rules } = data;
    const numPoints = coords.length;
    const STOP = actions.length - 1;
    const stepsFrom = coords.map(() => []);
    const jumpsFrom = coords.map(() => []);
    actions.forEach(([src, dst, over], id) => {
      if (src === null) return;
      (over === null ? stepsFrom : jumpsFrom)[src].push({ id, dst, over });
    });

    function initialState() {
      const trewas = new Array(numPoints).fill(false);
      data.trewasStart.forEach((p) => { trewas[p] = true; });
      return { komikelu: data.komikeluStart, trewas, toMove: KOMIKELU, inChain: false, captured: 0, plies: 0 };
    }

    function komikeluActions(s) {
      const out = [];
      for (const j of jumpsFrom[s.komikelu]) {
        if (s.trewas[j.over] && !s.trewas[j.dst]) out.push(j.id);
      }
      if (s.inChain) {
        out.push(STOP);
      } else {
        for (const m of stepsFrom[s.komikelu]) if (!s.trewas[m.dst]) out.push(m.id);
      }
      return out;
    }

    function legalActions(s) {
      if (s.toMove === KOMIKELU) return komikeluActions(s);
      const out = [];
      for (let p = 0; p < numPoints; p++) {
        if (!s.trewas[p]) continue;
        for (const m of stepsFrom[p]) {
          if (!s.trewas[m.dst] && m.dst !== s.komikelu) out.push(m.id);
        }
      }
      return out;
    }

    function applyAction(s, action) {
      const [src, dst, over] = actions[action];
      if (s.toMove === TREWAS) {
        const trewas = s.trewas.slice();
        trewas[src] = false;
        trewas[dst] = true;
        return { ...s, trewas, toMove: KOMIKELU, plies: s.plies + 1 };
      }
      if (action === STOP) return { ...s, toMove: TREWAS, inChain: false, plies: s.plies + 1 };
      if (over === null) return { ...s, komikelu: dst, toMove: TREWAS, plies: s.plies + 1 };

      const trewas = s.trewas.slice();
      trewas[over] = false;
      const next = { ...s, komikelu: dst, trewas, captured: s.captured + 1, inChain: true };
      // The turn passes automatically when no further jump exists.
      const options = komikeluActions(next);
      return options.length === 1 && options[0] === STOP ? applyAction(next, STOP) : next;
    }

    function outcome(s) {
      if (s.captured >= rules.capturesToWin) return KOMIKELU;
      if (!s.inChain && legalActions(s).length === 0) return s.toMove === KOMIKELU ? TREWAS : KOMIKELU;
      if (s.plies >= rules.maxPlies) return DRAW;
      return null;
    }

    function encodeObservation(s) {
      const obs = new Float32Array(2 * numPoints + 3);
      obs[s.komikelu] = 1;
      for (let p = 0; p < numPoints; p++) if (s.trewas[p]) obs[numPoints + p] = 1;
      obs[obs.length - 3] = s.inChain ? 1 : 0;
      obs[obs.length - 2] = s.captured / rules.capturesToWin;
      obs[obs.length - 1] = s.plies / rules.maxPlies;
      return obs;
    }

    return { actions, coords, rules, numPoints, STOP, initialState, legalActions, applyAction, outcome, encodeObservation };
  }

  // A ReLU MLP stored as float32 values: w0, b0, w1, b1, ...
  function createPolicy(engine, values, shapes) {
    const layers = [];
    let offset = 0;
    for (const [rows, cols] of shapes) {
      const weights = values.slice(offset, offset + rows * cols);
      offset += rows * cols;
      const biases = values.slice(offset, offset + rows);
      offset += rows;
      layers.push({ rows, cols, weights, biases });
    }
    if (offset !== values.length) throw new Error("agent weights do not match their declared shapes");

    function logits(obs) {
      let x = obs;
      layers.forEach((layer, index) => {
        const out = new Float32Array(layer.rows);
        for (let r = 0; r < layer.rows; r++) {
          let sum = layer.biases[r];
          const start = r * layer.cols;
          for (let c = 0; c < layer.cols; c++) sum += layer.weights[start + c] * x[c];
          out[r] = index < layers.length - 1 ? Math.max(sum, 0) : sum;
        }
        x = out;
      });
      return x;
    }

    // Samples from the policy's masked distribution, as the training benchmarks do.
    function selectAction(state, random) {
      const legal = engine.legalActions(state);
      const scores = logits(engine.encodeObservation(state));
      const best = Math.max(...legal.map((a) => scores[a]));
      const probs = legal.map((a) => Math.exp(scores[a] - best));
      let pick = random() * probs.reduce((a, b) => a + b, 0);
      for (let i = 0; i < legal.length; i++) {
        pick -= probs[i];
        if (pick <= 0) return legal[i];
      }
      return legal[legal.length - 1];
    }

    return { logits, selectAction };
  }

  root.Komikan = { KOMIKELU, TREWAS, DRAW, createEngine, createPolicy };
})(globalThis);
